"""Daily work and project entry points using real, paginated server data."""

WORKSPACE_JS = r"""
const WS={view:'',q:'',offset:0,read:0,lastScope:null};
function wsRefresh(){vWorkspace().catch(e=>toast(e.message))}
function wsProject(key,route){setProj(key);S.scope=key;ls.set('tmh.scope',key);location.hash=route||'#/projects/'+encodeURIComponent(key)}
function wsTaskRow(t,review=false){const action=review?'开始复核':t.status==='verify'?'查看验证':t.status==='confirm'?'确认方案':t.status==='new'?'开始处理':'继续处理';return `<article class="ws-row"><span class="ws-task-marker ${h(t.status)}" aria-hidden="true"></span><div class="grow"><a class="ws-row-title" href="#/t/${encodeURIComponent(t.key)}">${h(t.title)}</a><div class="ws-row-meta">${h(t.key)} · ${h(t.assignee||'待分配负责人')} ${t.reviewer?'· 复核 '+h(t.reviewer):''} · ${h(ago(t.updated))}</div></div>${stPill(t.status)}<a class="btn ghost" href="${review?'#/team/ticket/':'#/t/'}${encodeURIComponent(t.key)}">${action}</a></article>`}
async function vWorkspace(){
  const request=++WS.read, route=location.hash, scope=scopeQ();
  if(WS.lastScope!==scope){WS.offset=0;WS.lastScope=scope}
  const data=await get('/api/workspace?project='+encodeURIComponent(scopeQ())+'&view='+encodeURIComponent(WS.view||(S.meta.login?'mine':'team'))+'&q='+encodeURIComponent(WS.q)+'&offset='+WS.offset);
  if(request!==WS.read||route!==location.hash||scope!==scopeQ())return;
  if(data.total&&WS.offset>=data.total){WS.offset=Math.floor((data.total-1)/30)*30;return vWorkspace()}
  const labels={mine:'我负责的',review:'待我复核',unassigned:'待分配',team:'团队进行中'};
  $('#main').innerHTML=`<div class="ws-head"><div><div class="ws-eyebrow">${h(data.viewer||'团队')} · ${data.project==='*'?'全部项目':h(data.project)}</div><h1>工作台</h1></div><div class="wk-toolbar"><button class="primary" onclick="newTicket()">新建任务</button></div></div>
  <div class="ws-columns"><section><div class="ws-queue-tabs" role="group" aria-label="工作范围">${Object.entries(labels).map(([key,label])=>`<button data-ws-view="${key}" class="${key===data.view?'on':''}" aria-pressed="${key===data.view}">${label}<span>${data.counts[key]}</span></button>`).join('')}</div>
  <form class="ws-search" id="wsSearchForm"><label for="wsSearch">查找任务</label><input type="search" id="wsSearch" placeholder="任务名称、编号或负责人" value="${h(WS.q)}"><button>搜索</button></form>
  <div class="ws-list">${data.items.length?data.items.map(t=>wsTaskRow(t,data.view==='review')).join(''):`<div class="ws-empty"><h2>${WS.q?'没有找到匹配任务':data.view==='mine'?'当前没有分配给你的任务':data.view==='review'?'当前没有待你复核的任务':'当前队列没有任务'}</h2><p>${WS.q?'换个关键词，或清除搜索查看全部。':'可以查看团队任务、认领工作，或创建一项新任务。'}</p><a class="btn" href="#/team/unassigned">查看团队分配</a></div>`}</div>
  <div class="ws-pagination"><span class="sub">${data.total?`${data.offset+1}–${Math.min(data.offset+30,data.total)} / ${data.total} 项`:'0 项'}</span><button id="wsPrev" ${!data.offset?'disabled':''}>上一页</button><button id="wsNext" ${!data.has_more?'disabled':''}>下一页</button></div></section>
  <aside class="ws-aside"><section class="ws-panel"><div class="hdr"><h2 class="grow">项目接力</h2><a href="#/projects">全部项目</a></div>${data.projects.length?data.projects.map(p=>`<a class="ws-project-line" href="#/handoff/${encodeURIComponent(p.key)}"><span class="ws-project-avatar">${h(p.key.slice(0,2))}</span><span class="grow"><b>${h(p.name)}</b><small>${p.open} 项进行中 · 项目讲解与交接</small></span>${workIcon('next')}</a>`).join(''):'<p class="sub">连接代码仓库后，可生成项目讲解和交接说明。</p>'}</section>
  <section class="ws-panel ws-memory-callout"><span class="ws-eyebrow">团队知识</span><h2>查找处理经验</h2><p class="sub">按同类工单查找历史改法、适用范围与验证记录。</p><a class="btn" href="#/memory/clusters">查看问题归类 ${workIcon('next')}</a></section>
  <section class="ws-panel"><h2>常用入口</h2><div class="ws-quicklinks"><a href="#/team/review">代码复核与合并 ${workIcon('next')}</a><a href="#/reform">推进重构计划 ${workIcon('next')}</a><a href="#/deliveries">查看交付记录 ${workIcon('next')}</a></div></section></aside></div>`;
  document.querySelectorAll('[data-ws-view]').forEach(b=>b.onclick=()=>{WS.view=b.dataset.wsView;WS.offset=0;wsRefresh()});
  $('#wsSearchForm').onsubmit=e=>{e.preventDefault();WS.q=$('#wsSearch').value;WS.offset=0;wsRefresh()};
  $('#wsPrev').onclick=()=>{WS.offset=Math.max(0,WS.offset-30);wsRefresh()};$('#wsNext').onclick=()=>{WS.offset+=30;wsRefresh()};
}
async function vProjects(key){
  const route=location.hash, request=++WS.read;
  if(key){const p=S.projects.find(p=>p.key===key);if(!p)throw apiErr('没有这个项目，请返回项目列表。');setProj(key);S.scope=key;ls.set('tmh.scope',key);paintSel();
    const d=await get('/api/workspace?project='+encodeURIComponent(key)+'&view=team');
    if(route!==location.hash||request!==WS.read||S.proj!==key)return;
    $('#main').innerHTML=`<div class="ws-head"><div><a class="sub" href="#/projects">项目 /</a><h1>${h(p.name)}</h1><p class="sub">${h(p.description||'连接项目、任务与团队经验。')}</p></div><div class="wk-toolbar">${p.workflow==='reference'?'':'<button onclick="newTicket()">新建任务</button>'}<a class="btn primary" href="#/handoff/${encodeURIComponent(key)}">项目讲解与交接</a></div></div>
    <div class="ws-columns"><section><div class="ws-panel ws-project-intro"><span class="ws-eyebrow">${h(key)} · ${p.workflow==='reference'?'参考知识项目':'开发与维护项目'}</span><h2>从当前进度继续</h2><p>${d.counts.team} 项任务进行中。打开任务查看现象、下一步和相关依据，或进入团队协作分配负责人。</p><div class="wk-toolbar"><a class="btn" href="#/team/team" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">分配与复核</a><a class="btn" href="#/reform">重构计划</a><a class="btn" href="#/versions">版本记录</a></div></div><div class="hdr"><h2 class="grow">进行中的任务</h2><a href="#/tickets" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">全部任务</a></div><div class="ws-list">${d.items.length?d.items.map(t=>wsTaskRow(t)).join(''):'<div class="ws-empty"><h2>项目已连接</h2><p>创建任务，或先查看项目讲解了解代码和业务。</p></div>'}</div>${d.has_more?'<p class="sub">这里展示最近 30 项。<a href="#/tickets">打开全部任务</a></p>':''}</section>
    <aside class="ws-aside"><section class="ws-panel"><h2>理解这个项目</h2><div class="ws-quicklinks"><a href="#/handoff/${encodeURIComponent(key)}">项目讲解与交接 ${workIcon('next')}</a><a href="#/atlas">业务与代码图谱 ${workIcon('next')}</a><a href="#/kb">项目知识页 ${workIcon('next')}</a><a href="#/memory/clusters" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">同类问题与经验 ${workIcon('next')}</a><a href="#/library">参考项目与引用 ${workIcon('next')}</a></div></section><section class="ws-panel"><h2>项目工具</h2><div class="ws-quicklinks"><a href="#/runs">智能体运行 ${workIcon('next')}</a><a href="#/overview">监控总览 ${workIcon('next')}</a><a href="#/int">外部系统 ${workIcon('next')}</a><a href="#/settings">项目配置 ${workIcon('next')}</a></div></section></aside></div>`;return}
  const data=await get('/api/workspace?project=*&view=team');
  if(route!==location.hash||request!==WS.read)return;
  $('#main').innerHTML=`<div class="ws-head"><div><span class="ws-eyebrow">团队项目</span><h1>项目</h1><p class="sub">进入项目接着做，或先读一份有来源的交接说明。</p></div><button class="primary" onclick="newProject()">连接项目</button></div><label class="ws-project-search">查找项目<input type="search" id="wsProjectSearch" placeholder="项目名称、编号或描述"></label><div class="ws-list" id="wsProjects"></div>`;
  const draw=q=>{const ps=data.projects.filter(p=>(p.key+' '+p.name+' '+p.description).toLowerCase().includes(q.toLowerCase()));$('#wsProjects').innerHTML=ps.length?ps.map(p=>`<article class="ws-row"><span class="ws-project-avatar">${h(p.key.slice(0,2))}</span><div class="grow"><a class="ws-row-title" href="#/projects/${encodeURIComponent(p.key)}">${h(p.name)}</a><div class="ws-row-meta">${h(p.key)} · ${h(p.description||'尚未填写项目说明')}</div></div><span class="sub">${p.open} 项进行中</span><a class="btn" href="#/handoff/${encodeURIComponent(p.key)}">交接说明</a><a class="btn ghost" href="#/projects/${encodeURIComponent(p.key)}">进入项目 ${workIcon('next')}</a></article>`).join(''):'<div class="ws-empty"><h2>没有匹配的项目</h2><p>连接现有代码仓库后，就可以创建任务并积累团队知识。</p><button onclick="newProject()">连接项目</button></div>'};draw('');$('#wsProjectSearch').oninput=e=>draw(e.target.value);
}
function ticketWorkspaceCard(d){const a=d.team_assignment||{};return `<section class="card ws-ticket-team"><h2>协作与知识</h2><dl><dt>负责人</dt><dd>${h(a.assignee||d.ticket.assignee||'待分配')}</dd><dt>复核人</dt><dd>${h(a.reviewer||'待分配')}</dd></dl><div class="ws-quicklinks"><a href="#/team/ticket/${encodeURIComponent(d.ticket.key)}">分配任务 / 提交与复核代码 ${workIcon('next')}</a><a href="#/handoff/${encodeURIComponent(d.project.key)}">项目讲解与交接 ${workIcon('next')}</a><a href="#/memory/clusters" onclick="S.scope=S.proj;ls.set('tmh.scope',S.scope)">同类问题与解决经验 ${workIcon('next')}</a></div></section>`}
"""
